(function(){
  window.GM_info={scriptHandler:'Tampermonkey',version:'5.3.2',script:{name:'script5',version:'1.0',description:'',author:'',namespace:'',includes:[],matches:[],excludes:[],resources:{},'run-at':'document-end',options:{}},scriptMetaStr:'',scriptSource:'',uuid:'gm-'+Date.now()};
  window.unsafeWindow=window;
  window.GM_xmlhttpRequest=function(opt){
    var url=opt.url;
    var isCross=false;
    try{isCross=(new URL(url).origin!==location.origin);}catch(e){}
    if(isCross){
      try{
        var px=new XMLHttpRequest();
        px.open('POST','/proxy.php',true);
        px.setRequestHeader('Content-Type','application/json');
        var payload=JSON.stringify({url:url,method:opt.method||'GET',headers:opt.headers||{},body:opt.data!=null?opt.data:null});
        px.onload=function(){
          var resp={status:px.status,statusText:px.statusText,readyState:4,finalUrl:url,responseHeaders:px.getAllResponseHeaders(),responseText:px.responseText,response:px.response,context:opt.context||null};
          try{if(opt.onload)opt.onload(resp);}catch(e){}
        };
        px.onerror=function(){if(opt.onerror)opt.onerror({error:'proxy error',status:px.status,readyState:4});};
        px.ontimeout=function(){if(opt.onerror)opt.onerror({error:'timeout',status:0});};
        px.send(payload);
      }catch(e){if(opt.onerror)opt.onerror({error:e.message});}
    }else{
      try{
        var xhr=new XMLHttpRequest();
        xhr.open((opt.method||'GET'),url,true);
        var h=opt.headers||{};
        for(var k in h){if(k.toLowerCase()!=='accept-encoding'&&k.toLowerCase()!=='content-length'){try{xhr.setRequestHeader(k,h[k]);}catch(e){}}}
        if(opt.responseType){try{xhr.responseType=opt.responseType;}catch(e){}}
        xhr.onload=function(){
          var rh=xhr.getAllResponseHeaders();
          var resp={status:xhr.status,statusText:xhr.statusText,readyState:4,finalUrl:url,responseHeaders:rh,responseText:xhr.responseText,response:xhr.response,context:opt.context||null};
          try{if(opt.onload)opt.onload(resp);}catch(e){}
        };
        xhr.onerror=function(){if(opt.onerror)opt.onerror({error:'XHR error',status:xhr.status,readyState:4});};
        xhr.ontimeout=function(){if(opt.onerror)opt.onerror({error:'timeout',status:0});};
        xhr.send(opt.data!=null?opt.data:null);
      }catch(e){if(opt.onerror)opt.onerror({error:e.message});}
    }
  };
  window.GM_setValue=function(k,v){try{localStorage.setItem('gm_'+k,JSON.stringify(v));}catch(e){}};
  window.GM_getValue=function(k,d){try{var v=localStorage.getItem('gm_'+k);return v?JSON.parse(v):d;}catch(e){return d;}};
  window.GM_deleteValue=function(k){try{localStorage.removeItem('gm_'+k);}catch(e){}};
  window.GM_listValues=function(){var r=[];for(var i=0;i<localStorage.length;i++){var k=localStorage.key(i);if(k.indexOf('gm_')===0)r.push(k.slice(3));}return r;};
  window.GM_addStyle=function(css){var s=document.createElement('style');s.textContent=css;document.head.appendChild(s);return s;};
  window.GM_registerMenuCommand=function(){};
  window.GM_notification=function(t){alert(typeof t==='string'?t:(t.title||'')+' '+(t.text||''));};
  window.GM_setClipboard=function(t){try{navigator.clipboard&&navigator.clipboard.writeText(t);}catch(e){}};
  window.GM_getResourceText=function(){return '';};
  window.GM_getResourceURL=function(){return '';};
  window.GM={xmlhttpRequest:window.GM_xmlhttpRequest,setValue:window.GM_setValue,getValue:window.GM_getValue,deleteValue:window.GM_deleteValue,listValues:window.GM_listValues,addStyle:window.GM_addStyle,notification:window.GM_notification,setClipboard:window.GM_setClipboard,info:window.GM_info};
})();


